handleEvent(event) {
  switch (event.type) {
    case "submit":
      this.#onSubmit(event);
      break;
    case "input":
      this.#onInput(event);
      break;
    case "reset":
      this.reset();
      this.#onInput();
      this.focus();
      break;
    case "keyup":
      if (event.key === "Escape" && this.#input.value) {
        this.reset();
        this.#onInput();
        event.preventDefault();
        event.stopPropagation();
      }
      break;
  }
}
